/**
 * Embedded images, so the template needs no files in /public and makes no network requests.
 *
 * - `PHONE_BODIES`: three iPhone body renders (780 x 1595 px, transparent screen) that the screen content sits behind.
 * - `STATUS_ICONS`: the signal, Wi-Fi and battery group for the status bar.
 * - `MOON_COLOR` and `MOON_RELIEF`: grayscale lunar colour and height maps. The night sky lights them to
 *   draw the moon with real craters (a procedural moon is the fallback if they fail to load).
 *
 * Replace any of them with your own files by swapping the string for an imported or public URL.
 */
export const PHONE_BODIES = {
  blue: "data:image/webp;base64,",
  silver: "data:image/webp;base64,",
  orange: "data:image/webp;base64,",
} as const;

export const STATUS_ICONS = "data:image/png;base64,";

export const MOON_COLOR = "data:image/jpeg;base64,";

export const MOON_RELIEF = "data:image/jpeg;base64,";
